## Why This Is Asked
Tests cross-language async callbacks, memory ownership, and CGO safety; covers concurrency, resource lifetimes, and proper freeing of C-allocated buffers.

## Key Concepts
- cgo.Handle for passing Go values to C
- CGO callbacks and Go pointer rules
- Memory ownership: C allocates, Go frees
- Synchronization: mutex-protected maps and channels

## Code Example
```c
// header
typedef void (*job_cb)(int id, const char* result, size_t len, void* user);
void start_job(int id, job_cb cb, void* user);
void free_buf(char* buf);
```

```go
// binding sketch using cgo.Handle
type JobHandle struct {
    id     int
    handle cgo.Handle
    result chan string
    done   chan struct{}
}

var (
    jobs   = make(map[int]chan string)
    jobsMu sync.Mutex
)

//export jobCallback
func jobCallback(id C.int, result *C.char, len C.size_t, user unsafe.Pointer) {
    handle := cgo.Handle(user)
    if ch, ok := handle.Value().(chan string); ok {
        jobsMu.Lock()
        defer jobsMu.Unlock()
        jobs[id] = ch
        ch <- C.GoStringN(result, C.int(len))
    }
}

func (j *JobHandle) Wait() (string, error) {
    select {
    case res := <-j.result:
        return res, nil
    case <-time.After(timeout):
        return "", fmt.Errorf("timeout")
    }
}

func (j *JobHandle) Close() {
    j.handle.Delete()
    close(j.result)
}
```

